package com.popwam.mobile.onboarding

import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.drawscope.withTransform
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.semantics

/**
 * Android's Compose Multiplatform resource painter cannot decode SVG files. These vectors use the
 * exact filled path geometry exported from the approved Figma nodes, while remaining common code
 * for Android and the planned iOS host. The path data is intentionally kept verbatim.
 */
@Composable
internal fun PopMarkVector(
    color: Color,
    contentDescription: String?,
    modifier: Modifier = Modifier,
) = ExactOnboardingVector(PopMarkAsset, color, contentDescription, modifier)

@Composable
internal fun ThemeSystemVector(color: Color, modifier: Modifier = Modifier) =
    ExactOnboardingVector(ThemeSystemAsset, color, null, modifier)

@Composable
internal fun ThemeLightVector(color: Color, modifier: Modifier = Modifier) =
    ExactOnboardingVector(ThemeLightAsset, color, null, modifier)

@Composable
internal fun ThemeDarkVector(color: Color, modifier: Modifier = Modifier) =
    ExactOnboardingVector(ThemeDarkAsset, color, null, modifier)

@Composable
internal fun ChevronVector(color: Color, modifier: Modifier = Modifier) =
    ExactOnboardingVector(ChevronAsset, color, null, modifier)

@Composable
private fun ExactOnboardingVector(
    asset: ExactVectorAsset,
    color: Color,
    description: String?,
    modifier: Modifier,
) {
    val path = remember(asset.pathData) {
        PathParser().parsePathString(asset.pathData).toPath(Path())
    }
    val accessibleModifier = if (description == null) {
        modifier
    } else {
        modifier.semantics { contentDescription = description }
    }

    Canvas(accessibleModifier) {
        val scale = minOf(size.width / asset.viewportWidth, size.height / asset.viewportHeight)
        val offsetX = (size.width - asset.viewportWidth * scale) / 2f
        val offsetY = (size.height - asset.viewportHeight * scale) / 2f
        withTransform({
            translate(offsetX, offsetY)
            scale(scale, scale, Offset.Zero)
            translate(asset.translationX, asset.translationY)
            if (asset.flipY) scale(1f, -1f, Offset.Zero)
        }) {
            drawPath(path, color)
        }
    }
}

private data class ExactVectorAsset(
    val viewportWidth: Float,
    val viewportHeight: Float,
    val pathData: String,
    val translationX: Float = 0f,
    val translationY: Float = 0f,
    val flipY: Boolean = false,
)

